import React from 'react';
import {Composition} from 'remotion';
import {ExampleScene} from './ExampleScene';

/**
 * 在这里注册合成。ExampleScene 是接线参考（绿幕数字人 + 字幕 + BGM），
 * 正式项目按分镜复制改造或替换为自己的场景组件后在此注册。
 */
export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="example"
        component={ExampleScene}
        durationInFrames={60}
        fps={30}
        width={960}
        height={540}
        defaultProps={{}}
      />
    </>
  );
};
import React from 'react';
import {AbsoluteFill, Audio, staticFile} from 'remotion';
import {ChromaKeyVideo} from './ChromaKeyVideo';

/**
 * 接线参考：浅色背景 + 右侧绿幕数字人（canvas 抠像）+ 底部字幕 + BGM。
 * 所有 src 一律 staticFile() 包一次；素材文件名与项目路径保持 ASCII。
 */
export const ExampleScene: React.FC = () => {
  return (
    <AbsoluteFill style={{backgroundColor: '#F4F6FA'}}>
      <ChromaKeyVideo
        src="presenter.mp4"
        loop
        style={{position: 'absolute', right: 40, bottom: 0, height: '55%'}}
      />
      <div
        style={{
          position: 'absolute',
          bottom: 24,
          width: '100%',
          textAlign: 'center',
          fontFamily: 'Noto Sans CJK SC, sans-serif',
          fontSize: 30,
          color: '#1A2233',
          background: 'rgba(255,255,255,0.75)',
          padding: '6px 18px',
          borderRadius: 999,
        }}
      >
        示例字幕：逐句时间轴来自 tts_page.py 的 timings.json
      </div>
      <Audio src={staticFile('bgm.wav')} volume={0.2} />
    </AbsoluteFill>
  );
};

