import React, {useEffect, useRef} from 'react';
import {Video, staticFile, useCurrentFrame, useVideoConfig, continueRender, delayRender} from 'remotion';

export type ChromaKeyVideoProps = {
  /** public/ 下的相对路径；组件内部已包 staticFile，调用处传原始路径，勿再包一次 */
  src: string;
  /** 画布定位样式（position/width/left 等） */
  style?: React.CSSProperties;
  /** 抠像键色，默认纯绿 [0, 255, 0]；先取素材角落实测再填 */
  keyColor?: [number, number, number];
  /** 颜色距离阈值，超过即视为背景；默认 80，边缘粗糙可调 */
  threshold?: number;
  /** 素材短于场景时长时循环播放 */
  loop?: boolean;
  playbackRate?: number;
};

/**
 * 绿幕视频逐帧抠像：canvas 读帧 → 键色→透明、其余→不透明。
 * ffmpeg libvpx 在常见构建下写不出 alpha WebM，Remotion 也无内置 ChromaKeyVideo，
 * 绿幕数字人统一走本组件，不要改用 ffmpeg 预抠。
 *
 * 帧精确原理：Video 保持 paused，由本组件按当前帧显式 seek，
 * 等 seeked 事件（解码完成）后再 drawImage。不能依赖 <Video> 自动同步——
 * 渲染期它不保证当前帧已解码，第 0 帧会画出纯黑、其他帧可能描到旧帧。
 */
export const ChromaKeyVideo: React.FC<ChromaKeyVideoProps> = ({
  src,
  style,
  keyColor = [0, 255, 0],
  threshold = 80,
  loop = false,
  playbackRate = 1,
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();

  useEffect(() => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) {
      return;
    }
    let cancelled = false;
    let released = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    let onSeeked: (() => void) | undefined;
    const handle = delayRender(`chroma-key-draw`);
    const release = () => {
      if (!released) {
        released = true;
        continueRender(handle);
      }
    };

    const draw = () => {
      if (cancelled) {
        return;
      }
      if (canvas.width !== video.videoWidth) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
      }
      const ctx = canvas.getContext('2d', {willReadFrequently: true});
      if (!ctx) {
        release();
        return;
      }
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      const image = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const [kr, kg, kb] = keyColor;
      const soft = threshold * 0.6;
      const {data} = image;
      for (let i = 0; i < data.length; i += 4) {
        const dist = Math.hypot(data[i] - kr, data[i + 1] - kg, data[i + 2] - kb);
        // 方向勿反：键色→透明，主体→不透明
        data[i + 3] =
          dist >= threshold

